import itertools
from collections import Counter


def _route_solver(exact, minimum_duration):
    def solve(data):
        required = data.get("required", [])
        full = (1 << len(required)) - 1
        initial_mask = sum(1 << i for i, name in enumerate(required)
                           if name == data["source"])
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        # State includes coupon use and required-node visits: neither is a
        # property of the current node alone.
        start = data["start"]
        initial = (data["source"], 0, initial_mask)
        best = {initial: start}
        queue = [(start, data["source"], 0, initial_mask)]
        while queue:
            time, node, used, mask = heapq.heappop(queue)
            state = (node, used, mask)
            if best.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (not exact or used == data["coupons"])):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_node = edge["v"]
                    next_mask = mask
                    for i, name in enumerate(required):
                        if name == next_node:
                            next_mask |= 1 << i
                    next_state = (next_node, next_used, next_mask)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, next_node, next_used,
                                               next_mask))
        return {"arrival": None}
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]

        choices = []
        for name in names:
            rows = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, []) and
                    (name not in pins or row["version"] == pins[name])]
            rows.sort(key=lambda row: row["version"], reverse=True)
            choices.append([row["version"] for row in rows] + [None])

        for vector in itertools.product(*choices):
            versions = dict(zip(names, vector))
            if any(versions.get(name) is None or
                   not bounds[0] <= versions[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            # Traverse the root closure, enforcing all incoming constraints.
            reached = set()
            graph = {}
            stack = [(name, bounds[0], bounds[1])
                     for name, bounds in roots.items()]
            valid = True
            while stack and valid:
                name, low, high = stack.pop()
                version = versions.get(name)
                if version is None or not low <= version <= high:
                    valid = False
                    break
                if name in reached:
                    continue
                reached.add(name)
                row = next(row for row in packages[name]
                           if row["version"] == version)
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                graph[name] = [dep["name"] for dep in deps]
                for dep in deps:
                    stack.append((dep["name"], dep["min"], dep["max"]))
            if not valid or any(versions[name] is not None
                                for name in names if name not in reached):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in graph.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in reached):
                continue
            return {"versions": {name: versions[name] for name in names
                                 if name in reached}}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        if not mandatory.issubset({job["id"] for job in jobs}):
            return {"error": "impossible"}
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for selected in itertools.combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in selected))
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in selected)
            if any(not low <= counts[group] <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in selected:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            valid = True
            for _, delta in sorted(events):
                active += delta
                if active > 2:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


